# ---------------------------------------------------------------- 标签索引

def tag_index():
    idx = {}
    for k, n, d in Q.AXES:
        idx["AX:" + k] = {"label": n, "kind": "axis", "ref": k, "search": d}
    for k, n in Q.HOOKS.items():
        idx["HK:" + k] = {"label": n, "kind": "hook", "ref": k, "search": n}
    for t in Q.TOPICS:
        idx["TP:" + t["id"]] = {"label": t["name"], "kind": "topic", "ref": t["id"], "search": t.get("term", "")}
    for k, n, s in Q.ORIENTATIONS:
        idx["ORIENT:" + k] = {"label": n, "kind": "orient", "ref": k, "search": s}
    return idx


_ALIASES = None


def aliases():
    global _ALIASES
    if _ALIASES is not None:
        return _ALIASES
    a = {}
    for key, meta in tag_index().items():
        a.setdefault(meta["label"], key)
        for piece in str(meta["search"]).split("/"):
            piece = piece.strip()
            if piece:
                a.setdefault(piece, key)
    for name, key in (
        ("百合", "ORIENT:YURI"), ("GL", "ORIENT:YURI"), ("レズ", "ORIENT:YURI"), ("femslash", "ORIENT:YURI"),
        ("女性向", "ORIENT:FEMDOM"), ("乙女", "ORIENT:FEMDOM"), ("GB", "ORIENT:FEMDOM"), ("梦女", "ORIENT:FEMDOM"),
        ("男性向", "ORIENT:FM"), ("BG", "ORIENT:FM"),
    ):
        a.setdefault(name, key)
    _ALIASES = a
    return a


def normalize_tag(raw):
    """中文名 / 别名 / 规范 key → 规范 key；无法识别返回 None。"""
    s = str(raw or "").strip()
    if not s:
        return None
    idx = tag_index()
    if s in idx:
        return s
    a = aliases()
    if s in a:
        return a[s]
    for prefix in ("ORIENT:", "TP:", "HK:", "AX:"):
        if prefix + s in idx:
            return prefix + s
    return None


def buckets():
    """返回原始桶数据，供前端注入。"""
    return RECO_BUCKETS


def for_topic(topic_id):
    """兼容旧调用：取 TP:<id> 桶，展平成带 type 字段的列表。"""
    b = RECO_BUCKETS.get("TP:" + topic_id, {})
    items = []
    for m in MEDIA:
        for w in b.get(m, []):
            d = dict(w)
            d.setdefault("type", m)
            items.append(d)
    return items


# ---------------------------------------------------------------- 推荐计算

def _score_work(w, tag, main, soft, hooks, topics, lang_mode, length):
    s = 0
    why = []
    if tag in topics:
        s += 5
        why.append("推荐题材")
    if tag.startswith("AX:"):
        k = tag[3:]
        if k in main:
            s += 4
            why.append("主轴")
        elif k in soft:
            s += 2
            why.append("副轴")
    if tag.startswith("HK:") and tag[3:] in hooks:
        s += 3
        why.append("命中钩子")
    if lang_mode == 0 and w.get("language", "zh") == "zh":
        s += 1
    if length and w.get("length") == length:
        s += 1
    return s, why


def for_profile(profile):
    """按坐标 + 阅读条件返回三类作品清单（命令行版）。"""
    media = set(profile.get("media") or MEDIA)
    main = set(profile.get("main") or [])
    soft = set(profile.get("soft") or [])
    hooks = set(profile.get("hooks") or [])
    topics = set("TP:" + t for t in (profile.get("topics") or []))
    taboos = set(profile.get("taboos") or [])
    lang_mode = profile.get("language", 2)
    length = profile.get("length") or ""

    taboo_hooks = set()
    taboo_map = dict((t[0], t[2]) for t in Q.TABOOS)
    for tid in taboos:
        for h in taboo_map.get(tid, []):
            taboo_hooks.add(h)

    out = {m: [] for m in MEDIA}
    seen = {}
    for tag, bucket in RECO_BUCKETS.items():
        for m in MEDIA:
            for w in bucket.get(m, []):
                if m not in media:
                    continue
                if "ORIENT_FEMDOM" in taboos and w.get("orientation", "FM") == "FEMDOM":
                    continue
                if taboo_hooks & set(w.get("avoid") or []):
                    continue
                if lang_mode == 0 and w.get("language", "zh") == "ja":
                    continue
                s, why = _score_work(w, tag, main, soft, hooks, topics, lang_mode, length)
                wid = w.get("id") or w.get("title")
                rec = {"work": w, "score": s, "why": why, "tags": [tag]}
                if wid in seen:
                    prev = seen[wid]
                    prev["score"] += s
                    prev["why"] += why
                    prev["tags"].append(tag)
                else:
                    seen[wid] = rec
                    out[m].append(rec)
    for m in MEDIA:
        out[m].sort(key=lambda r: (-r["score"], r["work"].get("year") or 0, r["work"].get("title", "")))
    return out


# ---------------------------------------------------------------- 校验

def validate():
    errs = []
    idx = tag_index()
    ids = {}
    for tag, bucket in RECO_BUCKETS.items():
        if tag not in idx:
            errs.append("未知标签桶: " + tag)
        for m, items in bucket.items():
            if m not in MEDIA:
                errs.append("未知媒体: %s / %s" % (tag, m))
            for w in items:
                label = "%s/%s/%s" % (tag, m, w.get("id") or w.get("title") or "?")
                for f in REQUIRED:
                    if not w.get(f):
                        errs.append("缺字段 %s: %s" % (f, label))
                if w.get("media") != m:
                    errs.append("媒体不符 %s: media=%s 桶=%s" % (label, w.get("media"), m))
                for field, valid in (("language", VALID_LANG), ("length", VALID_LENGTH),
                                     ("orientation", VALID_ORIENT)):
                    val = w.get(field, "" if field != "orientation" else "FM")
                    if val and val not in valid:
                        errs.append("%s 非法 %s: %s" % (field, label, val))
                wid = w.get("id")
                if wid:
                    key = (tag, m, wid)
                    if key in ids:
                        errs.append("桶内重复 id %s: %s" % (wid, key))
                    else:
                        ids[key] = label
    return errs


def stats():
    total = len(RECO_BUCKETS)
    items = sum(len(v) for b in RECO_BUCKETS.values() for v in b.values())
    return total, items


def cmd_tags():
    bykind = {}
    for key, meta in tag_index().items():
        bykind.setdefault(meta["kind"], []).append((key, meta["label"]))
    names = {"axis": "轴", "hook": "钩子", "topic": "题材", "orient": "取向"}
    for kind in ("axis", "hook", "topic", "orient"):
        rows = bykind.get(kind, [])
        print("\n── %s (%d) ──" % (names[kind], len(rows)))
        for key, label in rows:
            print("  %-24s %s" % (key, label))
    print("\n── 常用别名 ──")
    for a, k in sorted(aliases().items()):
        if a != k:
            print("  %-12s → %s" % (a, k))


def cmd_check():
    errs = validate()
    total, items = stats()
    print("  桶 %d / 作品 %d" % (total, items))
    if errs:
        print("  发现 %d 处问题：" % len(errs))
        for e in errs:
            print("   - " + e)
    else:
        print("  校验通过。")


def main():
    args = sys.argv[1:]
    if args and args[0] == "tags":
        cmd_tags()
        return
    if args and args[0] == "check":
        cmd_check()
        return
    cmd_check()


if __name__ == "__main__":
    main()
